on conflict (code) where code is not null do nothing;

-- guard: every component resolved to a catalog recipe or ingredient
do $$
declare v_bad text;
begin
  select string_agg(m.code, ', ') into v_bad from public.meals m, jsonb_array_elements(m.components) c
   where m.code is not null and m.household_id is null
     and coalesce(c ->> 'recipe_id', c -> 'ingredient_ids' ->> 0) is null;
  if v_bad is not null then
    raise exception '092_meals: unresolved components in %', v_bad;
  end if;
end $$;

