insert into public.meal_alternatives (meal_id, alternative_meal_id, reason, notes, review_status)
select m.id, a.id, v.reason, v.notes, 'in_review'
from (values
  ('D001', 'D001-A', 'autism', 'Same family meal served deconstructed on a divided plate: sauce on the side, the child portion lifted out before chilli is added, plain cucumber sticks as the crunchy side. Add the child''s safe food in the free section.'),
